import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '../../../components/BackButton'
import type { Comment, Post } from '../../../lib/types'

// Equivalent of `getStaticPaths` with `fallback: 'blocking'`: params not
// returned here are rendered on demand (dynamicParams defaults to true).
export const dynamicParams = true

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 }, // 5 minutes
  })
  if (!res.ok) return null
  return res.json()
}

async function getComments(id: string): Promise<Comment[] | null> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } } // 5 minutes
  )
  if (!res.ok) return null
  return res.json()
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>
}): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {}
  }

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  }
}

export default async function BlogPost({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params

  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  if (!post || !comments) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

